import os
import sys

def find_null_bytes(root_dir):
    for root, dirs, files in os.walk(root_dir):
        for file in files:
            path = os.path.join(root, file)
            try:
                with open(path, 'rb') as f:
                    content = f.read()
                    if b'\x00' in content:
                        # Check if it's followed by 'tty'
                        if b'\x00tty' in content:
                            print(path)
            except Exception:
                pass

if __name__ == "__main__":
    find_null_bytes(sys.argv[1])

